
import { serviceTypes } from '../../../mocks/shops';

interface ServiceFilterProps {
  selectedServices: string[];
  onToggleService: (serviceId: string) => void;
}

export default function ServiceFilter({
  selectedServices,
  onToggleService,
}: ServiceFilterProps) {
  return (
    <div className="bg-white border border-gray-200 rounded-xl p-5">
      <h3 className="font-bold text-gray-900 mb-4 flex items-center gap-2 text-sm">
        <i className="ri-tools-line text-red-500 w-5 h-5 flex items-center justify-center"></i>
        サービス内容で絞り込み
      </h3>

      <div className="space-y-1.5">
        {serviceTypes.map((service) => (
          <button
            key={service.id}
            onClick={() => onToggleService(service.id)}
            className={`w-full text-left py-2.5 px-3 rounded-lg text-sm transition-colors cursor-pointer flex items-center gap-2.5 ${
              selectedServices.includes(service.id)
                ? 'bg-red-50 text-red-700 font-bold border border-red-200'
                : 'bg-gray-50 text-gray-700 hover:bg-red-50 hover:text-red-600 border border-transparent'
            }`}
          >
            <i className={`${service.icon} w-4 h-4 flex items-center justify-center`}></i>
            <span>{service.name}</span>
            {selectedServices.includes(service.id) && (
              <i className="ri-check-line ml-auto text-red-600"></i>
            )}
          </button>
        ))}
      </div>
    </div>
  );
}
